export type ReactionOffer = {
	ready: boolean,
	source: TokenId,
	rule: string,
	action: string,
	label: Label,
};

/**  Why an intent or message was rejected. The `code` tag is stable and safe to match on in clients. */
export type RejectReason = 
/**  `expected_version` did not match; `current` is the entity's version now (ADR-0003). */
{ code: "stale_version"; current: Version } | 
/**  A checked intent was sent without `expected_version`. */
{ code: "missing_expected_version" } | 
/**  The actor's role does not allow this intent. */
{ code: "forbidden" } | 
/**  The referenced entity does not exist. */
{ code: "not_found" } | 
/**  An entity with this id already exists. */
{ code: "already_exists" } | 
/**  The intent is malformed; `field` names the offending field. */
{ code: "invalid"; field: string } | 
/**
 *  The `intent_id` was already used for an intent with different data. Any retry with changed
 *  data (e.g. a new `expected_version`) needs a new `intent_id` (ADR-0015).
 */
{ code: "intent_id_reused" } | 
/**
 *  A size limit of the target would be exceeded (e.g. too many fog operations on a map);
 *  `limit` names it. Retrying the same intent cannot succeed.
 */
{ code: "limit_exceeded"; limit: string } | 
/**  Client and server speak different protocol versions. */
{ code: "protocol_mismatch"; server: number; client: number };

/**  An intent was not applied. */
export type Rejection = {
	intent_id: IntentId,
	reason: RejectReason,
};

/**  A session this app hosted or joined (no secrets). */
export type RemoteEntry = {
	/**  Local campaign uploaded by this GM; absent for joined and older saved sessions. */
	local_campaign?: string | null,
	server: string,
	session_id: SessionId,
	session_name: string,
	/**  Uploaded from this app (its GM key is in the keychain). */
	hosted: boolean,
	/**  The participant's name, role and campaign user once joined. */
	name: string | null,
	role: Role | null,
	user_id: UserId | null,
	invite_url: string | null,
	/**  The access code, for the GM to pass on (from the keychain, never stored in the list). */
	access_code: string | null,
	saved_at_ms: number,
};

/**  The connected session, for the status bar and the hosting screen. */
export type RemoteInfo = {
	server: string,
	session_id: SessionId,
	session_name: string,
	role: Role,
	hosted: boolean,
	status: RemoteStatus,
};

/**  Connection state for the status bar. */
export type RemoteStatus = { state: "connecting" } | { state: "online" } | { state: "reconnecting"; attempt: number; retry_in_ms: number } | { state: "closed"; reason: string };

/**  The connection to the session server changed. */
export type RemoteStatusChanged = RemoteStatus;

export type RequiredTurn = "own" | "other";

/**  A generalized hit-point-like resource. `value` and `max` are expressions. */
export type ResourceDef = {
	id: string,
	label: Label,
	value: string,
	max: string,
};

/**
 *  Who a damage/healing step applies to. Zone and map targets need a firing map; the zone is
 *  matched by name on that map, like zone events.
 */
export type ResourceTarget = 
/**  The character who set the trigger off (legacy behavior). */
{ type: "activator" } | 
/**  Every distinct character with a token inside the zone of this name on the firing map. */
{ type: "zone"; id: ZoneId } | 
/**  Every distinct character with a token on the firing map. */
{ type: "map" };

export type ResourceValue = {
	id: string,
	value: number | null,
	max: number | null,
};

/**  Something triggers can show to players. */
export type RevealTarget = 
/**  A board node becomes open to players. */
{ kind: "node"; id: BoardNodeId } | 
/**  A board is shown to players. */
{ kind: "board"; id: BoardId } | { kind: "map"; id: MapId } | 
/**  A journal entry is shared with players. */
{ kind: "journal"; id: JournalEntryId } | 
/**  A token becomes visible. */
{ kind: "token"; id: TokenId };

/**  Role of a participant (CLAUDE.md §5). */
export type Role = "gm" | "co_gm" | "player" | "spectator";

/**  A roll macro shown on the sheet. */
export type RollDef = {
	kind?: RollKind | null,
	tags?: string[],
	id: string,
	label: Label,
	dice: string,
};

export type RollKind = "attack" | "save" | "check" | "initiative";

export type RollMode = "advantage" | "disadvantage";

/**
 *  One roll someone owes the table. Created by a `change_resource` trigger step with
 *  `manual: true`; players see the requests of their own characters, GM roles see all of them.
 */
export type RollRequestDto = {
	id: RollRequestId,
	/**  What the roller sees ("Poisoned dart"). */
	label: string,
	trigger: TriggerId,
	character: CharacterId,
	token: TokenId | null,
	/**  The roll the controller makes; `@` fields read the character's sheet. */
	dice: string,
	/**
	 *  An attack/check: `@total` is the roll, the character's fields evaluate the condition;
	 *  the resource changes only on a hit. `None`: a plain roll always applies.
	 */
	hit: string | null,
	/**  What a hit (or a plain roll) applies to the character's `resource`. */
	resource: string,
	damage_dice: string,
	heal: boolean,
	status: RollRequestStatus,
	total: number | null,
	/**  The applied resource delta, reversed when a GM cancels a rolled request. */
	delta: number | null,
	version: Version,
};

/**  A manual roll a trigger asked a character's controller for. */
export type RollRequestId = string;

/**  Where a [`RollRequestDto`] stands. */
export type RollRequestStatus = 
/**  Waiting for the controller's roll. */
"pending" | 
/**  Rolled; `delta` holds the applied resource change, if the roll hit. */
"rolled" | 
/**  Dismissed by a GM role; a rolled request's delta has been reversed. */
"cancelled";

/**  Read-only statistics over authorized, persisted dice rolls. */
export type RollStatisticsDto = {
	user_id: UserId | null,
	/**  Last recorded name in the authorized history, not an identity key. */
	name: string,
	rolls: number,
	average: number | null,
	minimum: number,
	maximum: number,
	natural_ones: number,
	natural_twenties: number,
};

export type RuleCapability = "action" | "bonus_action" | "reaction" | "movement" | "provoke";

export type RuleSubject = "actor" | "target";

/**
 *  Position of an event in the campaign/session event log.
 * 
 *  Exported to TypeScript as `number` (ADR-0007).
 */
export type Seq = number;

/**  Server → client. */
export type ServerMessage = { type: "events"; payload: EventBatch } | 
/**  Boxed: by far the largest message (keeps `ServerMessage` small). */
{ type: "snapshot"; payload: Snapshot } | 
/**
 *  The sender's intent was applied (or had been: a repeat, ADR-0015). Its events arrive in
 *  `events` like everyone else's.
 */
{ type: "accepted"; payload: Acceptance } | { type: "rejected"; payload: Rejection } | { type: "pong" } | 
/**
 *  Answer to `get_journal_entry`; `entry` is `None` when it is gone or not visible to the
 *  recipient.
 */
{ type: "journal_entry"; payload: {
	id: JournalEntryId,
	entry: JournalEntryDto | null,
} };

/**  A session on the session server. */
export type SessionId = string;

/**  What a sheet shows besides its data (numbers as JSON numbers for the UI). */
export type SheetView = {
	economy?: TurnEconomyView | null,
	modifiers?: Label[],
	computed: { [key in string]: number | null },
	resources: ResourceValue[],
};

/**  The visible state as of event `seq`. */
export type Snapshot = {
	plugin_runtime?: PluginRuntime,
	/**  Sequence number of the last event included (0 = no events yet). */
	seq: Seq,
	campaign: CampaignMeta,
	maps: MapDto[],
	tokens: TokenDto[],
	characters: CharacterDto[],
	users: UserDto[],
	/**  Journal index; texts are fetched per entry. */
	journal: JournalEntryMeta[],
	/**  Journal folders (ADR-0021). */
	journal_folders: JournalFolderDto[],
	assets: AssetDto[],
	/**  Fog of maps that have any (ADR-0019). */
	fog: FogDto[],
	/**  Combats and their combatants (ADR-0020). */
	combats: CombatDto[],
	combatants: CombatantDto[],
	/**  The last `CHAT_SNAPSHOT_LEN` chat messages, oldest first. */
	chat: ChatMessageDto[],
	/**  Plugins installed in the campaign (ADR-0023). */
	plugins: PluginDto[],
	/**  Id of the campaign's system plugin. */
	system_plugin: string | null,
	/**  Boards with their nodes and edges (ADR-0024). */
	boards: BoardDto[],
	board_nodes: BoardNodeDto[],
	board_edges: BoardEdgeDto[],
	/**  Zones on maps (GM roles only; empty for players). */
	zones: ZoneDto[],
	/**  Triggers (GM roles only; empty for players). */
	triggers: TriggerDto[],
	/**  Folders of the image and audio libraries (GM roles only; empty for players, ADR-0026). */
	library_folders?: LibraryFolderDto[],
	/**  Looping or paused sounds, with the last commanded position for reconnecting clients. */
	sounds?: SoundDto[],
	playlists?: PlaylistDto[],
	/**  Temporary effects on tokens (ADR-0024); filtered with their tokens. */
	effects?: TokenEffectDto[],
	/**
	 *  Manual rolls triggers asked for; every role receives them (the widget filters by
	 *  character ownership), GM roles see and manage all of them.
	 */
	roll_requests?: RollRequestDto[],
};

/**
 *  A sound being played to everyone. The file is the audio asset's own (`sha256`), named neither
 *  here nor to players: the hash is enough to fetch it (ADR-0026).
 */
export type SoundDto = {
	asset_id: AssetId,
	sha256: string,
	mime: string,
	/**  0..=`MAX_VOLUME`, scaled by each listener's own volume. */
	volume: number,
	/**  Plays until stopped (music); a sound that does not loop plays once. */
	looped: boolean,
	/**  Last commanded position; no wall clock or drift correction (ADR-0028). */
	position_ms?: number,
	paused?: boolean,
	/**
	 *  One-shot that ducks the background: clients pause looping sounds and resume them from
	 *  their positions when this sting ends (never retained in the snapshot).
	 */
	sting?: boolean,
};

/**  Where tokens created by a trigger land on the firing map (Units16, ADR-0016). */
export type SpawnPlacement = 
/**  An exact point; later tokens fan out around it. */
{ type: "point"; x: number; y: number } | 
/**  A random point inside the zone (per token). */
{ type: "zone"; id: ZoneId };

/**  Messages the core posts; the UI localizes them by `code`. */
export type SystemMessage = { code: "plugin_action_resolved"; action?: IntentId | null; label: Label; outcome: ActionResolution } | { code: "character_submitted"; name: string } | { code: "character_approved"; name: string } | { code: "character_returned"; name: string } | 
/**  A trigger's narration line (ADR-0024). */
{ code: "narration"; text: string } | 
/**  A trigger changed a resource of the character `name` by `delta`. */
{ code: "resource_changed"; name: string; resource: string; delta: number } | 
/**  A trigger put a condition on (`added`) or took it off the character `name`. */
{ code: "condition_changed"; name: string; condition: string; added: boolean } | 
/**  The character `name` received an item. */
{ code: "item_given"; name: string; item: string } | 
/**  A trigger asks `name` for a manual roll (`label`). */
{ code: "roll_requested"; name: string; label: string } | 
/**  A GM role dismissed the roll (`label`) of `name`. */
{ code: "roll_request_cancelled"; name: string; label: string };

/**  The rules of a system plugin, self-contained (no package paths). */
export type SystemRulesDto = {
	mechanics?: PluginMechanics,
	features?: PluginFeatureDef[],
	/**  Sheet data schema (JSON Schema subset, see `sheet_schema`). */
	sheet_schema: unknown,
	/**  Root layout node (rendered by the clients; the core only stores it). */
	sheet_layout: unknown,
	/**  Optional NPC/creature form over the same validated system data. */
	creature_sheet_layout?: unknown | null,
	/**  Name → expression; results are integers. */
	computed: { [key in string]: string },
	/**  Dice expression for initiative. */
	initiative: string,
	resources: ResourceDef[],
	/**  Strictly descending percents: Healthy / Wounded / Critical / Dead boundaries. */
	health_thresholds: number[],
	rolls: RollDef[],
	/**  Conditions characters may have; rules installed before they existed have none. */
	conditions?: ConditionDef[],
	/**  The sheet list of items, if the system has one. */
	inventory?: InventoryDef | null,
};

/**  A column of a journal table. */
export type TableColumn = {
	name: string,
	/**  Width on screen, in CSS pixels (`MIN_COLUMN_WIDTH..=MAX_COLUMN_WIDTH`). */
	width: number,
};

/**  One blank of a trigger template. */
export type TemplateParam = {
	id: string,
	label: Label,
	kind: TemplateParamKind,
};

/**  What a template parameter asks for (the GM fills it in when creating the trigger). */
export type TemplateParamKind = "zone" | "board_node" | "board" | "map" | "journal" | "token" | 
/**  A roll of the system. */
"roll" | 
/**  A resource of the system. */
"resource" | 
/**  A condition of the system. */
"condition" | "number" | "text";

export type ThemeDto = {
	light?: { [key in string]: string },
	dark?: { [key in string]: string },
};

/**  Whose side a token is on: GM bookkeeping for frames and quick scans. */
export type TokenDisposition = "neutral" | "ally" | "enemy";

/**  A token on a map. */
export type TokenDto = {
	id: TokenId,
	map_id: MapId,
	character_id: CharacterId | null,
	asset_id: AssetId | null,
	name: string,
	/**  Position in 1/16 logical map units (ADR-0016), `0..=width*16`. */
	x: number,
	y: number,
	/**  Degrees, clockwise. */
	rotation: number,
	scale: number,
	layer: TokenLayer,
	/**  Whose side the token is on; missing in legacy data: neutral. */
	disposition?: TokenDisposition,
	visible: boolean,
	version: Version,
};

/**  A temporary effect hanging on a token. */
export type TokenEffectDto = {
	id: EffectId,
	token: TokenId,
	/**  Shown name (the potion, the trap, ...). */
	label: string,
	/**  A condition id of the system, shown as a badge. */
	condition: string | null,
	/**  Resource changed by `dice` at the start of each of the token's turns, if any. */
	resource: string | null,
	dice: string | null,
	/**  `true`: the recurring change heals instead of damaging. */
	heal: boolean,
	duration: EffectDuration,
	version: Version,
};

/**  A token placed on a map. */
export type TokenId = string;

/**  Rendering layer of a token. */
export type TokenLayer = 
/**  Below regular tokens (props, terrain). */
"background" | 
/**  Regular tokens. */
"tokens" | 
/**  Visible to GM / Co-GM only. */
"gm";

/**  What a trigger does, step by step. Character actions apply to the character who set it off. */
export type TriggerAction = 
/**  An installed system action; source defaults to the activating token. */
{ type: "plugin_action"; action: string; source: TokenId | null; target: TokenId | null; x: number; y: number } | 
/**  Shows something to players. */
{ type: "reveal"; target: RevealTarget } | 
/**  Hides a board node again (or opens it: any visibility). */
{ type: "set_node_visibility"; node: BoardNodeId; visibility: BoardVisibility } | 
/**  A narration line in the chat; `gm_only` keeps it from players. */
{ type: "chat"; text: string; gm_only: boolean } | 
/**  Rolls dice (with the character's fields); later steps see the total as `@roll`. */
{ type: "roll"; dice: string; label: string } | 
/**
 *  Damage (`heal: false`) or healing by a dice roll, kept within 0..=max of the resource.
 *  Without `attack`, one roll is shared by every target; `attack` rolls per target and
 *  applies only on a hit. `manual` asks the targets' controllers to roll instead.
 */
{ type: "change_resource"; resource: string; dice: string; heal: boolean; 
/**  Who takes the change; missing in legacy data: the activator. */
target?: ResourceTarget; attack?: AttackCheck | null; manual?: boolean } | { type: "add_condition"; condition: string } | { type: "remove_condition"; condition: string } | { type: "give_item"; name: string } | 
/**  Plays an audio asset to everyone (ADR-0026). */
{ type: "play_sound"; asset: AssetId; volume: number; looped: boolean } | 
/**  Stops a looping sound; `None`: all sounds. */
{ type: "stop_sound"; asset: AssetId | null } | 
/**  Spawns `count` tokens of a character on the firing map (ADR-0024). */
{ type: "spawn_tokens"; character: CharacterId; count: number; placement: SpawnPlacement } | 
/**
 *  Opens a combat on the firing map: every visible character token joins and rolls
 *  initiative by the system's formula.
 */
{ type: "start_combat" } | 
/**
 *  A one-shot sound: background music pauses for everyone and resumes from its position
 *  when the sting ends.
 */
{ type: "play_sting"; asset: AssetId; volume: number } | 
/**  Puts a temporary effect on the firing token (ADR-0024). */
{ type: "apply_effect"; label: string; 
/**  A condition id of the system to show, if any. */
condition: string | null; 
/**  A resource changed by `dice` at the start of each of the token's turns, if any. */
resource: string | null; dice: string | null; heal: boolean; duration: EffectDurationDef };

/**  What the GM edits: everything of a trigger but its id, state and version. */
export type TriggerDef = {
	name: string,
	enabled: boolean,
	/**  Fires at most once per bound map (until edited again). */
	once: boolean,
	/**
	 *  Maps where this trigger runs. Empty legacy zone definitions infer the zone's map;
	 *  other empty legacy definitions retain their campaign-wide behavior.
	 */
	map_ids?: MapId[],
	event: TriggerEvent,
	/**  Tokens that may set it off; empty: any token of a character. */
	tokens: TokenId[],
	/**  Must hold (`dnd-expr` over the character's fields and `@total`) for the trigger to fire. */
	condition: string | null,
	steps: TriggerStep[],
};

/**  A trigger of the campaign. */
export type TriggerDto = {
	id: TriggerId,
	definition: TriggerDef,
	/**  A `once` trigger that already fired. */
	fired: boolean,
	/**  Bound maps already spent by a once trigger; edits clear this list. */
	fired_maps?: MapId[],
	version: Version,
};

/**  What sets a trigger off. */
export type TriggerEvent = 
/**
 *  A character whose token stands in `zone` made one of `rolls` (system roll ids; empty:
 *  any system roll). `@total` is the roll's total.
 */
{ type: "roll_in_zone"; zone: ZoneId; rolls: string[] } | 
/**  A token that was outside `zone` is now inside. */
{ type: "token_entered_zone"; zone: ZoneId } | 
/**  The GM's button (`fire_trigger`). */
{ type: "manual" } | 
/**  A character's inventory gained an item called `name` (ignoring case). */
{ type: "item_received"; name: string };

/**  Who set a trigger off (for the GM's log). */
export type TriggerFiredDto = {
	trigger: TriggerId,
	name: string,
	character: CharacterId | null,
	token: TokenId | null,
	/**  Map context; absent in legacy/global firings. */
	map_id?: MapId | null,
};

/**  A trigger: when → if → then, run by the core (ADR-0024). */
export type TriggerId = string;

/**  One action and, optionally, the expression that must hold for it to run. */
export type TriggerStep = {
	when: string | null,
	action: TriggerAction,
};

/**
 *  A ready-made trigger a plugin ships (`triggers/<name>.json`, ADR-0024): a trigger definition
 *  whose strings may contain `{{param}}` blanks. Data only; the trigger made from it is checked
 *  by the core like any other.
 */
export type TriggerTemplateDto = {
	id: string,
	name: Label,
	description: Label | null,
	params: TemplateParam[],
	/**  A `TriggerDef` with blanks (so not typed until they are filled). */
	definition: unknown,
};

/**  Resource refill policy. Amount is the desired balance, not an additive grant. */
export type TurnBudget = {
	resource: string,
	label: Label,
	feature: string | null,
	refresh: BudgetRefresh,
	amount?: string | null,
};

export type TurnBudgetValue = {
	resource: string,
	label: Label,
	refresh: BudgetRefresh,
	remaining: number,
	reserved: number,
	limit: number,
};

export type TurnEconomyView = {
	in_combat: boolean,
	own_turn: boolean,
	turn_started: boolean,
	budgets: TurnBudgetValue[],
};

/**  An update that can be installed. */
export type UpdateAvailable = {
	version: string,
	current_version: string,
	notes: string | null,
};

/**  A user of the campaign. Read-only in stage 2a (users join through the session server, 2b). */
export type UserDto = {
	id: UserId,
	name: string,
	role: Role,
};

/**  A user known to the campaign (GM, players). */
export type UserId = string;

/**
 *  Optimistic-concurrency version of a mutable entity (ADR-0003). Starts at 1.
 * 
 *  Exported to TypeScript as `number`: versions never approach 2^53 (ADR-0007).
 */
export type Version = number;

/**  A named zone on a map. */
export type ZoneDto = {
	id: ZoneId,
	map_id: MapId,
	name: string,
	shape: ZoneShape,
	/**  Where the GM moved the name to; `None` (and zones stored before): at the first part's corner. */
	label?: ZoneLabel | null,
	/**  RGB, 0x000000..=0xffffff. Old campaigns use purple. */
	color?: number,
	version: Version,
};

/**  A named area on a map that triggers watch (ADR-0024). */
export type ZoneId = string;

/**  Where a zone's name is drawn: the top-left corner of the text, in Units16 (ADR-0016). */
export type ZoneLabel = {
	x: number,
	y: number,
};

/**  The area of a zone, in Units16 (ADR-0016). */
export type ZoneShape = 
/**  Axis-aligned rectangle with its top-left corner at (`x`, `y`). */
{ type: "rect"; x: number; y: number; width: number; height: number } | 
/**  A closed polygon: flat `[x0, y0, x1, y1, …]`, 3..=[`MAX_ZONE_POINTS`] points. */
{ type: "polygon"; points: number[] } | 
/**  Several rectangles and polygons (not unions) taken together: a zone added to or merged. */
{ type: "union"; parts: ZoneShape[] };

/* Tauri Specta runtime */
async function typedError<T, E>(result: Promise<T>): Promise<{ status: "ok"; data: T } | { status: "error"; error: E }> {
    try {
        return { status: "ok", data: await result };
    } catch (e) {
        if (e instanceof Error) throw e;
        return { status: "error", error: e as any };
    }
}

type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

